from typing import Optional
from fastapi import Header, Cookie


def get_client_id(
    x_client: Optional[str] = Header(None, alias="X-Client"),
    client_id: Optional[str] = Cookie(None, alias="client_id"),
) -> Optional[str]:
    """Return first non‑empty identifier from header or cookie."""
    return x_client or client_id
