# main.py
import pathlib

from fastapi import Depends, FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import HTMLResponse
from starlette.websockets import WebSocketCloseCode

from utils.deps import get_client_id

app = FastAPI()


@app.get("/", response_class=HTMLResponse)
async def get_root() -> HTMLResponse:
    """Serve the client HTML page."""
    html_path = pathlib.Path(__file__).parent / "templates" / "index.html"
    return HTMLResponse(content=html_path.read_text(encoding="utf-8"))


@app.websocket("/ws/{item_id}")
async def websocket_endpoint(
    websocket: WebSocket,
    item_id: str,
    q: str = None,
    client_id: str = Depends(get_client_id),
) -> None:
    """Echo received messages, adding request parameters."""
    await websocket.accept()

    # Policy violation if no client identifier is supplied
    if client_id is None:
        await websocket.close(code=WebSocketCloseCode.POLICY_VIOLATION)  # 1008
        return

    try:
        while True:
            data = await websocket.receive_text()
            reply = (
                f"Message text was: ID={item_id}, query={q}, "
                f"client={client_id}, data={data}"
            )
            await websocket.send_text(reply)
    except WebSocketDisconnect:
        # Normal disconnect – nothing to do
        pass
