<!-- templates/index.html -->
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>FastAPI WebSocket Demo</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 2rem; }
        input, button { margin: 0.5rem 0; }
        #messages { list-style: none; padding: 0; }
        #messages li { margin-bottom: 0.3rem; }
    </style>
</head>
<body>
    <h2>WebSocket client</h2>

    <label for="itemId">Item ID:</label><br>
    <input id="itemId" placeholder="item id"><br>

    <button onclick="connect(event)">Connect</button>

    <hr>

    <label for="msgInput">Message:</label><br>
    <input id="msgInput" placeholder="type a message"><br>
    <button onclick="sendMessage(event)">Send</button>

    <h3>Received messages</h3>
    <ul id="messages"></ul>

    <script>
        let ws = null;

        function connect(event) {
            event.preventDefault();
            const item = document.getElementById('itemId').value.trim();
            if (!item) {
                alert('Please enter an item ID');
                return;
            }
            const query = 'test';
            const url = `ws://${location.host}/ws/${encodeURIComponent(item)}?q=${encodeURIComponent(query)}`;
            ws = new WebSocket(url);

            ws.onopen = () => console.log('WebSocket opened');
            ws.onmessage = e => {
                const li = document.createElement('li');
                li.textContent = e.data;
                document.getElementById('messages').appendChild(li);
            };
            ws.onclose = e => console.log('WebSocket closed', e);
            ws.onerror = e => console.error('WebSocket error', e);
        }

        function sendMessage(event) {
            event.preventDefault();
            if (!ws || ws.readyState !== WebSocket.OPEN) {
                alert('WebSocket is not connected');
                return;
            }
            const msg = document.getElementById('msgInput').value;
            ws.send(msg);
            document.getElementById('msgInput').value = '';
        }
    </script>
</body>
</html>
